Offline-first y sincronización.ejemplo:
fun observeTasks(): Flow<List<Task>> = localDao.observeAll()

suspend fun syncPending() {
  val pending = localDao.getUnsynced()
  pending.forEach { api.upsert(it.id, it.toDto()); localDao.markSynced(it.id) }
}

